(()=>{const e=matchMedia("(prefers-reduced-motion: reduce)");document.addEventListener("pointerdown",t=>{if(!t.isPrimary||t.button!==0||e.matches||document.hidden)return;const s=document.querySelectorAll(".ink-click");s.length>=6&&s[0].remove();const n=document.createElement("span");n.className="ink-click",n.setAttribute("aria-hidden","true"),n.style.left=`${t.clientX}px`,n.style.top=`${t.clientY}px`,n.style.setProperty("--ink-angle",`${Math.random()*360}deg`);for(let t=0;t<7;t++){const e=document.createElement("span"),s=t/7*Math.PI*2+Math.random()*.5,o=18+Math.random()*29;e.className="ink-click-drop",e.style.setProperty("--dx",`${Math.cos(s)*o}px`),e.style.setProperty("--dy",`${Math.sin(s)*o}px`),e.style.setProperty("--drop-size",`${2+Math.random()*4}px`),n.appendChild(e)}document.body.appendChild(n),setTimeout(()=>n.remove(),1300)},{passive:!0})})()